<script setup lang="ts">
import {ref,watch,nextTick,computed} from 'vue'
import {hitFigure} from './boxRuntime'
import {personState,instanceName} from './people'
const props=defineProps<{project:Record<string,any>,zoom:number,selectedId?:string,disabled?:boolean,mode?:string,proposals?:Record<string,any>[]}>()
const emit=defineEmits(['select','changed','added'])
const hovered=ref(''),selected=ref(''),container=ref<HTMLElement|null>(null)
watch(()=>props.selectedId,async value=>{selected.value=value||'';await nextTick();const el=container.value?.querySelector(`[data-id="${selected.value}"]`);el?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})})
const labelled=computed(()=>props.project.annotations.find((a:any)=>a.id===(hovered.value||selected.value)))
let drag:any=null
function hit(e:PointerEvent){const r=(e.currentTarget as HTMLElement).getBoundingClientRect(),p=point(e);return hitFigure(props.project.annotations,p.x,p.y,r.width,r.height,selected.value,props.mode==='select')}
function point(e:PointerEvent){const r=(e.currentTarget as HTMLElement).getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
function down(e:PointerEvent){if(props.disabled)return;const start=point(e);const target=hit(e);selected.value=target?.id||'';emit('select',selected.value);const a=props.mode==='select'?props.project.annotations.find((a:any)=>a.id===selected.value):undefined;drag={start,a,before:a?{...a}:null,resize:!!target?.resize,clientX:e.clientX,clientY:e.clientY,left:container.value?.scrollLeft,top:container.value?.scrollTop};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(props.disabled)return;if(!drag){hovered.value=hit(e)?.id||'';return}if(props.mode==='pan'&&container.value){container.value.scrollLeft=drag.left-(e.clientX-drag.clientX);container.value.scrollTop=drag.top-(e.clientY-drag.clientY);return}if(!drag.a)return;const p=point(e),dx=p.x-drag.start.x,dy=p.y-drag.start.y;const a=drag.a,b=drag.before;if(drag.resize){a.w=Math.max(.005,Math.min(1-a.x,b.w+dx));a.h=Math.max(.005,Math.min(1-a.y,b.h+dy))}else{a.x=Math.max(0,Math.min(1-a.w,b.x+dx));a.y=Math.max(0,Math.min(1-a.h,b.y+dy))}a.confirmed=false;emit('changed',a.id)}
function up(e:PointerEvent){if(props.disabled){drag=null;return;}if(!drag)return;const p=point(e);if(props.mode==='add'&&!drag.a&&Math.abs(p.x-drag.start.x)>.01&&Math.abs(p.y-drag.start.y)>.01){const a={id:crypto.randomUUID().slice(0,12),x:Math.min(p.x,drag.start.x),y:Math.min(p.y,drag.start.y),w:Math.abs(p.x-drag.start.x),h:Math.abs(p.y-drag.start.y),description:'',kind:'character',characterId:'',confirmed:false};props.project.annotations.push(a);selected.value=a.id;emit('select',a.id);emit('added')}drag=null}
</script>
<template><div ref="container" class="image-scroll"><div class="painting" :style="{width:zoom+'%'}" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="drag=null" @pointerleave="hovered=''"><img :src="project.image" draggable="false"><div v-for="(a,i) in project.annotations" :data-id="a.id" class="editable-box" :class="[{selected:selected===a.id,hovered:hovered===a.id},personState(project,a).key]" :style="{left:a.x*100+'%',top:a.y*100+'%',width:a.w*100+'%',height:a.h*100+'%'}"><span v-if="mode==='select'&&selected===a.id" class="resize"/></div><span v-if="labelled" class="box-label" :style="{left:Math.min(.78,labelled.x)*100+'%',top:(labelled.y>.055?labelled.y*100:Math.min(.94,labelled.y+labelled.h)*100)+'%',transform:labelled.y>.055?'translateY(calc(-100% - 5px))':'translateY(5px)'}">{{instanceName(project,labelled)}}</span><div v-for="(a,i) in proposals||[]" class="proposal-box" :style="{left:a.x*100+'%',top:a.y*100+'%',width:a.w*100+'%',height:a.h*100+'%'}"><span>补检 {{Number(i)+1}}</span></div></div></div></template>
<style scoped>
.proposal-box{position:absolute;border:1px dashed #387bb180;pointer-events:none;color:#fff;font-size:11px}.proposal-box>span{background:#387bb1;padding:2px 4px}.editable-box{position:absolute;border:1px solid #b67b1b4d;background:transparent!important;pointer-events:none;outline:none!important}.editable-box.confirmed{border-color:#2380524d}.editable-box.unnamed{border-color:#7c85834d}.editable-box.hovered{border-color:#387e70b3}.editable-box.selected{border:2px solid #406ec0;z-index:2}.box-label{position:absolute;z-index:5;white-space:nowrap;background:#31594be6;color:white;font-size:11px;padding:3px 7px;border-radius:4px;line-height:18px;pointer-events:none;max-width:22%;overflow:hidden;text-overflow:ellipsis}.resize{position:absolute;bottom:-4px;right:-4px;width:8px;height:8px;background:white;border:1px solid #406ec0;cursor:nwse-resize;pointer-events:auto}.image-scroll{max-height:650px;overflow:auto}.painting{cursor:crosshair}
</style>
